        function renderEmbedDeptCheckbox(container, dept) {
            var listItem = document.createElement("li");
            listItem.className = "kh-form-check";
            container.appendChild(listItem);

            var input = document.createElement("input");
            input.className = "kh-form-check-input";
            input.type = "checkbox";
            input.id = "dept-" + dept.identifier;
            input.value = dept.identifier;
            input.name = "departments";
            input.onchange = function () { filterJobs(); };
            listItem.appendChild(input);

            var label = document.createElement("label");
            label.className = "kh-form-check-label kh-cursor-pointer kh-text-truncate-2 kh-pl-2";
            label.setAttribute("for", "dept-" + dept.identifier);
            label.innerHTML = dept.name;
            listItem.appendChild(label);
        }

        function bindFilters() {
            var departmentSelect = document.getElementById("kh-hiro-departments");
            if (departmentSelect) {
                if (!globalFilterGroupsData) {
                    // Flat mode: departments fetched directly, filter to only those with active jobs.
                    departmentList.forEach(function (department) {
                        var listItem = document.createElement("li");
                        listItem.className = "kh-form-check";
                        departmentSelect.appendChild(listItem);

                        var input = document.createElement("input");
                        input.className = "kh-form-check-input";
                        input.type = "checkbox";
                        input.id = department.identifier;
                        input.value = department.identifier;
                        input.name = "departments";
                        input.onchange = function () { filterJobs() };
                        listItem.appendChild(input);

                        var label = document.createElement("label");
                        label.className = "kh-form-check-label kh-cursor-pointer kh-text-truncate-2 kh-pl-2";
                        label.setAttribute("for", department.identifier);
                        label.innerHTML = department.name;
                        listItem.appendChild(label);
                    });
                } else {
                    // BU-linked mode.
                    // globalFilterGroupsData is an array with one entry whose groupList is flat,
                    // mixing BU items (systemGroupType=1) and dept link items (systemGroupType=100).
                    // parentNodeId identifies the BU; childNodeId/childNodeIdentifier identify the dept;
                    // parentGroupId identifies the direct parent (BU id when direct, link item id when nested).
                    var allGroupItems = (globalFilterGroupsData[0] && globalFilterGroupsData[0].groupList) || [];
                    var activeGroupLinkIds = jobList.map(function (j) { return j.groupLinkIdentifier; }).filter(Boolean);

                    // BU items filtered to those present in the fetched businessUnitList.
                    var buItems = allGroupItems.filter(function (item) {
                        return item.systemGroupType === 1 &&
                            businessUnitList.some(function (b) { return b.id === item.id; });
                    });

                    // Dept link items: must have a childNodeId, and childNodeIdentifier must exist
                    // in the fetched departmentList.
                    var deptLinkItems = allGroupItems.filter(function (item) {
                        return item.systemGroupType === 100 &&
                            item.childNodeId &&
                            departmentList.some(function (d) { return d.identifier === item.childNodeIdentifier; });
                    });

                    // Further narrow to links whose groupLinkIdentifier is present in at least one job.
                    var activeDeptLinks = deptLinkItems.filter(function (d) {
                        return activeGroupLinkIds.indexOf(d.identifier) !== -1;
                    });

                    buItems.forEach(function (bu) {
                        var buDeptLinks = activeDeptLinks.filter(function (d) { return d.parentNodeId === bu.id; });
                        if (!buDeptLinks.length) return;

                        // Resolve BU display name from businessUnitList.
                        var buData = businessUnitList.find(function (b) { return b.id === bu.id; });
                        var buName = buData ? buData.name : bu.name;

                        var buLi = document.createElement("li");
                        buLi.className = "kh-accordion-item kh-mt-3";
                        departmentSelect.appendChild(buLi);

                        var buTitleDiv = document.createElement("div");
                        buTitleDiv.className = "kh-accordion-title kh-d-flex kh-align-items-center kh-cursor-pointer";

                        var buCheckbox = document.createElement("input");
                        buCheckbox.type = "checkbox";
                        buCheckbox.className = "kh-form-check-input";
                        buCheckbox.id = "bu-select-" + bu.id;
                        buTitleDiv.appendChild(buCheckbox);

                        var buArrow = document.createElement("span");
                        buArrow.className = "ki-arrow-dropdown kh-d-flex kh-align-items-center kh-justify-content-center";
                        buTitleDiv.appendChild(buArrow);

                        var buLabel = document.createElement("label");
                        buLabel.className = "kh-form-check-label kh-cursor-pointer kh-pl-2 kh-font-large";
                        buLabel.setAttribute("for", "bu-select-" + bu.id);
                        buLabel.innerHTML = buName;
                        buTitleDiv.appendChild(buLabel);

                        buLi.appendChild(buTitleDiv);

                        var buContentDiv = document.createElement("div");
                        buContentDiv.className = "kh-accordion-content kh-ml-4";
                        buContentDiv.style.display = "none";
                        buLi.appendChild(buContentDiv);

                        var buDeptList = document.createElement("ul");
                        buDeptList.className = "kh-list-unstyled kh-my-2";
                        buContentDiv.appendChild(buDeptList);

                        // Direct links: parentGroupId === bu.id (no intermediate parent dept).
                        // Nested links: parentGroupId is another link item's id.
                        var directLinks = buDeptLinks.filter(function (d) { return d.parentGroupId === bu.id; });
                        var nestedLinks = buDeptLinks.filter(function (d) { return d.parentGroupId !== bu.id; });

                        // Group nested links by their immediate parentGroupId.
                        var parentDeptGroups = {};
                        nestedLinks.forEach(function (d) {
                            var pgId = d.parentGroupId;
                            if (!parentDeptGroups[pgId]) {
                                var parentLinkItem = allGroupItems.find(function (item) { return item.id === pgId; });
                                var pgName = '';
                                if (parentLinkItem) {
                                    // If the parent link item also maps to a dept, resolve its name from departmentList.
                                    if (parentLinkItem.childNodeIdentifier) {
                                        var pgDeptData = departmentList.find(function (dept) { return dept.identifier === parentLinkItem.childNodeIdentifier; });
                                        pgName = pgDeptData ? pgDeptData.name : parentLinkItem.name;
                                    } else {
                                        pgName = parentLinkItem.name;
                                    }
                                }
                                parentDeptGroups[pgId] = { name: pgName, links: [], linkItem: parentLinkItem };
                            }
                            parentDeptGroups[pgId].links.push(d);
                        });

                        // Render parent department sub-accordions.
                        Object.keys(parentDeptGroups).forEach(function (pgId) {
                            var pg = parentDeptGroups[pgId];
                            var pdItem = document.createElement("li");
                            pdItem.className = "kh-accordion-item kh-mt-2";
                            buDeptList.appendChild(pdItem);

                            var pdTitleDiv = document.createElement("div");
                            pdTitleDiv.className = "kh-accordion-title kh-d-flex kh-align-items-center kh-cursor-pointer";

                            var pdCheckbox = document.createElement("input");
                            pdCheckbox.type = "checkbox";
                            pdCheckbox.className = "kh-form-check-input";
                            pdCheckbox.id = "pd-select-" + pgId;
                            // When the parent link item maps to an active dept, the accordion header
                            // checkbox itself acts as the filter for the parent dept's own jobs —
                            // no separate leaf is needed.
                            if (pg.linkItem && pg.linkItem.childNodeIdentifier &&
                                activeGroupLinkIds.indexOf(pg.linkItem.identifier) !== -1) {
                                pdCheckbox.name = "departments";
                                pdCheckbox.value = pg.linkItem.identifier;
                            }
                            pdTitleDiv.appendChild(pdCheckbox);

                            var pdArrow = document.createElement("span");
                            pdArrow.className = "ki-arrow-dropdown kh-d-flex kh-align-items-center kh-justify-content-center";
                            pdTitleDiv.appendChild(pdArrow);

                            var pdLabel = document.createElement("label");
                            pdLabel.className = "kh-form-check-label kh-cursor-pointer kh-pl-2";
                            pdLabel.setAttribute("for", "pd-select-" + pgId);
                            pdLabel.innerHTML = pg.name;
                            pdTitleDiv.appendChild(pdLabel);

                            pdItem.appendChild(pdTitleDiv);

                            var pdContentDiv = document.createElement("div");
                            pdContentDiv.className = "kh-accordion-content kh-ml-4";
                            pdContentDiv.style.display = "none";
                            pdItem.appendChild(pdContentDiv);

                            var pdDeptList = document.createElement("ul");
                            pdDeptList.className = "kh-list-unstyled kh-my-2";
                            pdContentDiv.appendChild(pdDeptList);

                            pg.links.forEach(function (d) {
                                var deptData = departmentList.find(function (dept) { return dept.identifier === d.childNodeIdentifier; });
                                renderEmbedDeptCheckbox(pdDeptList, { identifier: d.identifier, name: deptData ? deptData.name : d.name });
                            });

                            // Checking parent dept selects all child dept checkboxes; unchecking clears them.
                            // Child checkboxes never alter the parent dept checkbox state — only the user does.
                            pdCheckbox.onchange = function () {
                                pdContentDiv.querySelectorAll('input[name="departments"]').forEach(function (cb) {
                                    cb.checked = pdCheckbox.checked;
                                });
                                filterJobs();
                            };

                            // Toggle accordion only when clicking outside the checkbox/label.
                            pdTitleDiv.addEventListener("click", function (e) {
                                if (e.target.tagName === "INPUT" || e.target.tagName === "LABEL") return;
                                pdContentDiv.style.display = pdContentDiv.style.display === "none" ? "block" : "none";
                            });
                        });

                        // Render dept links directly under BU, skipping any that already appear
                        // as a parent department accordion header above.
                        var parentDeptGroupIds = Object.keys(parentDeptGroups).map(Number);
                        directLinks.filter(function (d) {
                            return parentDeptGroupIds.indexOf(d.id) === -1;
                        }).forEach(function (d) {
                            var deptData = departmentList.find(function (dept) { return dept.identifier === d.childNodeIdentifier; });
                            renderEmbedDeptCheckbox(buDeptList, { identifier: d.identifier, name: deptData ? deptData.name : d.name });
                        });

                        // Checking BU selects all dept and parent-dept checkboxes underneath; unchecking clears them.
                        buCheckbox.onchange = function () {
                            var isChecked = buCheckbox.checked;
                            buContentDiv.querySelectorAll('input[name="departments"]').forEach(function (cb) {
                                cb.checked = isChecked;
                            });
                            // Sync parent department select-all checkboxes (no name attr, inside accordion titles).
                            buContentDiv.querySelectorAll('.kh-accordion-title input[type="checkbox"]').forEach(function (cb) {
                                cb.checked = isChecked;
                                cb.indeterminate = false;
                            });
                            filterJobs();
                        };

                        // Keep BU checkbox in sync when individual dept checkboxes change.
                        buContentDiv.addEventListener("change", function (e) {
                            if (e.target.name !== "departments") return;
                            var allDeptCbs = Array.from(buContentDiv.querySelectorAll('input[name="departments"]'));
                            var checkedCount = allDeptCbs.filter(function (cb) { return cb.checked; }).length;
                            buCheckbox.checked = checkedCount === allDeptCbs.length;
                            buCheckbox.indeterminate = checkedCount > 0 && checkedCount < allDeptCbs.length;
                        });

                        // Toggle accordion only when clicking outside the checkbox/label.
                        buTitleDiv.addEventListener("click", function (e) {
                            if (e.target.tagName === "INPUT" || e.target.tagName === "LABEL") return;
                            buContentDiv.style.display = buContentDiv.style.display === "none" ? "block" : "none";
                        });
                    });
                }
            }

            var jobTypeSelect = document.getElementById("kh-hiro-jobType");
            if (jobTypeSelect) {
                jobTypeList.forEach(function (jobType) {
                    var listItem = document.createElement("li");
                    listItem.className = "kh-form-check";
                    jobTypeSelect.appendChild(listItem);

                    var input = document.createElement("input");
                    input.className = "kh-form-check-input";
                    input.type = "checkbox";
                    input.id = jobType.id;
                    input.value = jobType.id;
                    input.name = "jobTypes";
                    input.onchange = function () { filterJobs() };
                    listItem.appendChild(input);

                    var label = document.createElement("label");
                    label.className = "kh-form-check-label kh-cursor-pointer kh-text-truncate-2 kh-pl-2";
                    label.setAttribute("for", jobType.id);
                    label.innerHTML = jobType.name;
                    listItem.appendChild(label);
                });
            }
            var locationSelect = document.getElementById("kh-hiro-locations");
            if (locationSelect) {

                // locationList: country >> city >> name
                const groupedLocations = locationList.reduce((groups, location) => {
                    if (location.countryName) {
                        const country = location.countryName;
                        const city = location.city || "";
                        const name = location.name || location.city;
                        if (!name) return groups;
                        if (!groups[country]) groups[country] = {};
                        if (!groups[country][city]) groups[country][city] = [];
                        const exists = groups[country][city].some(function (l) { return l.name === name; });
                        if (!exists) groups[country][city].push({ name: name, id: location.id });
                    }
                    return groups;
                }, {});

                if (locationListWithNoCountry.length) {
                    groupedLocations["Others"] = locationListWithNoCountry.reduce((others, location) => {
                        const city = location.name ?? location.city;
                        if (city) others.push(city);
                        return others;
                    }, groupedLocations["Others"] ?? []);
                }

                for (const [country, citiesOrNames] of Object.entries(groupedLocations)) {
                    const isOthers = country === "Others";
                    if (isOthers) {
                        const countryItem = document.createElement("li");
                        countryItem.className = "kh-accordion-item kh-mt-3";
                        locationSelect.appendChild(countryItem);
                        const titleDiv = document.createElement("div");
                        titleDiv.className = "kh-accordion-title kh-d-flex kh-align-items-center kh-cursor-pointer";
                        titleDiv.innerHTML = `
                            <input type="checkbox" class="kh-form-check-input country-checkbox" id="country-${country.replace(/\s/g, "-")}" value="${country}" name="locations">
                            <span class="ki-arrow-dropdown kch-description-color kh-d-flex kh-align-items-center kh-justify-content-center kh-pl-2"></span>
                            <label class="kh-form-check-label kh-cursor-pointer kh-text-truncate-2 kh-pl-2" for="country-${country.replace(/\s/g, "-")}">${country}</label>
                        `;
                        countryItem.appendChild(titleDiv);
                        const contentDiv = document.createElement("div");
                        contentDiv.className = "kh-accordion-content kh-ml-4";
                        contentDiv.style.display = "none";
                        countryItem.appendChild(contentDiv);
                        const cityList = document.createElement("ul");
                        cityList.className = "kh-list-unstyled kh-font-normal kh-my-2";
                        contentDiv.appendChild(cityList);
                        const othersList = Array.isArray(citiesOrNames) ? citiesOrNames : [];
                        othersList.forEach(function (cityVal) {
                            const cityItem = document.createElement("li");
                            cityItem.className = "kh-form-check";
                            cityList.appendChild(cityItem);
                            const cityCheckbox = document.createElement("input");
                            cityCheckbox.type = "checkbox";
                            cityCheckbox.className = "kh-form-check-input city-checkbox";
                            cityCheckbox.id = "others-" + String(cityVal).replace(/\s/g, "-") + country.replace(/\s/g, "-");
                            cityCheckbox.value = cityVal;
                            cityCheckbox.name = "locations";
                            cityCheckbox.onchange = function () {
                                const locationKey = JSON.stringify({ country: "Others", city: cityVal });
                                if (cityCheckbox.checked) selectedLocations.add(locationKey); else selectedLocations.delete(locationKey);
                                filterJobs();
                            };
                            cityItem.appendChild(cityCheckbox);
                            const cityLabel = document.createElement("label");
                            cityLabel.className = "kh-form-check-label kh-cursor-pointer kh-text-truncate-2 kh-pl-2";
                            cityLabel.setAttribute("for", cityCheckbox.id);
                            cityLabel.innerHTML = cityVal;
                            cityItem.appendChild(cityLabel);
                        });
                        titleDiv.addEventListener("click", function () {
                            const isExpanded = contentDiv.style.display === "block";
                            contentDiv.style.display = isExpanded ? "none" : "block";
                        });
                        const countryCheckbox = titleDiv.querySelector("input[type='checkbox']");
                        countryCheckbox.onchange = function () {
                            contentDiv.querySelectorAll("input[name='locations']").forEach(function (cb) {
                                cb.checked = countryCheckbox.checked;
                                const locationKey = JSON.stringify({ country: "Others", city: cb.value });
                                if (countryCheckbox.checked) selectedLocations.add(locationKey); else selectedLocations.delete(locationKey);
                            });
                            filterJobs();
                        };
                        continue;
                    }

                    const countryItem = document.createElement("li");
                    countryItem.className = "kh-accordion-item kh-mt-3";
                    locationSelect.appendChild(countryItem);

                    const titleDiv = document.createElement("div");
                    titleDiv.className = "kh-accordion-title kh-d-flex kh-align-items-center kh-cursor-pointer";
                    const countryId = "country-" + country.replace(/\s/g, "-");
                    titleDiv.innerHTML = `
                        <input type="checkbox" class="kh-form-check-input country-checkbox" id="${countryId}" value="${country}" name="locations">
                        <span class="ki-arrow-dropdown kch-description-color kh-d-flex kh-align-items-center kh-justify-content-center kh-pl-2"></span>
                        <label class="kh-form-check-label kh-cursor-pointer kh-text-truncate-2 kh-pl-2" for="${countryId}">${country}</label>
                    `;
                    countryItem.appendChild(titleDiv);

                    const contentDiv = document.createElement("div");
                    contentDiv.className = "kh-accordion-content kh-ml-4";
                    contentDiv.style.display = "none";
                    countryItem.appendChild(contentDiv);

                    const cityList = document.createElement("ul");
                    cityList.className = "kh-list-unstyled kh-font-normal kh-my-2";
                    contentDiv.appendChild(cityList);

                    for (const [city, names] of Object.entries(citiesOrNames)) {
                        const cityItem = document.createElement("li");
                        cityItem.className = "kh-accordion-item kh-mt-2";
                        cityList.appendChild(cityItem);

                        const cityTitleDiv = document.createElement("div");
                        cityTitleDiv.className = "kh-accordion-title kh-d-flex kh-align-items-center kh-cursor-pointer kh-font-normal";
                        const cityId = "city-" + country.replace(/\s/g, "-") + "-" + (city || "default").replace(/\s/g, "-");
                        const cityCheckboxId = "city-checkbox-" + cityId;
                        cityTitleDiv.innerHTML = `
                            <input type="checkbox" class="kh-form-check-input city-group-checkbox" id="${cityCheckboxId}" name="locations" value="${(city || "").replace(/"/g, "&quot;")}" data-country="${country.replace(/"/g, "&quot;")}">
                            <span class="ki-arrow-dropdown kch-description-color kh-d-flex kh-align-items-center kh-justify-content-center kh-pl-2"></span>
                            <span class="kh-pl-2 kh-text-truncate-2">${city || "—"}</span>
                        `;
                        cityItem.appendChild(cityTitleDiv);

                        const cityContentDiv = document.createElement("div");
                        cityContentDiv.className = "kh-accordion-content kh-ml-4";
                        cityContentDiv.style.display = "none";
                        cityItem.appendChild(cityContentDiv);

                        const nameList = document.createElement("ul");
                        nameList.className = "kh-list-unstyled kh-font-normal kh-my-2 kh-ml-4";
                        cityContentDiv.appendChild(nameList);

                        names.forEach(function (loc) {
                            const name = loc.name;
                            const locId = "loc-" + (loc.id != null ? loc.id : (country + "-" + city + "-" + name).replace(/\s/g, "-"));
                            const nameItem = document.createElement("li");
                            nameItem.className = "kh-form-check";
                            nameList.appendChild(nameItem);

                            const nameCheckbox = document.createElement("input");
                            nameCheckbox.type = "checkbox";
                            nameCheckbox.className = "kh-form-check-input city-checkbox";
                            nameCheckbox.id = locId;
                            nameCheckbox.value = name;
                            nameCheckbox.name = "locations";
                            nameCheckbox.onchange = function () {
                                handleNameCheckboxChange(country, citiesOrNames);
                            };
                            nameItem.appendChild(nameCheckbox);

                            const nameLabel = document.createElement("label");
                            nameLabel.className = "kh-form-check-label kh-cursor-pointer kh-text-truncate-2 kh-pl-2";
                            nameLabel.setAttribute("for", locId);
                            nameLabel.innerHTML = name;
                            nameItem.appendChild(nameLabel);
                        });

                        const cityCheckbox = cityTitleDiv.querySelector("input.city-group-checkbox");
                        cityCheckbox.onchange = function (e) {
                            e.stopPropagation();
                            const isChecked = cityCheckbox.checked;
                            names.forEach(function (loc) {
                                const name = loc.name;
                                const locationKey = JSON.stringify({ country, city, name });
                                const cb = document.getElementById("loc-" + String(loc.id != null ? loc.id : (country + "-" + city + "-" + name).replace(/\s/g, "-")));
                                if (cb) {
                                    cb.checked = isChecked;
                                    if (isChecked) selectedLocations.add(locationKey); else selectedLocations.delete(locationKey);
                                }
                            });
                            handleNameCheckboxChange(country, citiesOrNames);
                        };

                        cityTitleDiv.addEventListener("click", function (e) {
                            if (e.target === cityCheckbox || (e.target.tagName === "INPUT" && e.target.type === "checkbox" && e.target.classList.contains("city-group-checkbox"))) return;
                            const isExpanded = cityContentDiv.style.display === "block";
                            cityContentDiv.style.display = isExpanded ? "none" : "block";
                        });
                    }

                    titleDiv.addEventListener("click", function () {
                        const isExpanded = contentDiv.style.display === "block";
                        contentDiv.style.display = isExpanded ? "none" : "block";
                    });

                    const countryCheckbox = titleDiv.querySelector("input[type='checkbox']");
                    countryCheckbox.onchange = function () {
                        handleCountryCheckboxChange(country, citiesOrNames);
                    };
                }

                function handleNameCheckboxChange(country, citiesOrNames) {
                    const countryCheckbox = document.querySelector("#country-" + CSS.escape(country.replace(/\s/g, "-")));
                    if (!countryCheckbox) return;
                    var allChecked = true;
                    for (const city in citiesOrNames) {
                        if (!citiesOrNames.hasOwnProperty(city)) continue;
                        const names = citiesOrNames[city];
                        var cityAllChecked = true;
                        names.forEach(function (loc) {
                            const name = loc.name;
                            const locationKey = JSON.stringify({ country, city, name });
                            const cb = document.querySelector("#loc-" + CSS.escape(String(loc.id != null ? loc.id : (country + "-" + city + "-" + name).replace(/\s/g, "-"))));
                            if (cb) {
                                if (cb.checked) selectedLocations.add(locationKey); else selectedLocations.delete(locationKey);
                                cityAllChecked = cityAllChecked && cb.checked;
                                allChecked = allChecked && cb.checked;
                            }
                        });
                        const cityCheckboxId = "city-checkbox-city-" + country.replace(/\s/g, "-") + "-" + (city || "default").replace(/\s/g, "-");
                        const cityCheckboxEl = document.getElementById(cityCheckboxId);
                        if (cityCheckboxEl) cityCheckboxEl.checked = cityAllChecked;
                    }
                    countryCheckbox.checked = allChecked;
                    filterJobs();
                }

                function handleCountryCheckboxChange(country, citiesOrNames) {
                    const countryCheckbox = document.querySelector("#country-" + CSS.escape(country.replace(/\s/g, "-")));
                    if (!countryCheckbox) return;
                    const isChecked = countryCheckbox.checked;
                    for (const city in citiesOrNames) {
                        if (!citiesOrNames.hasOwnProperty(city)) continue;
                        const names = citiesOrNames[city];
                        names.forEach(function (loc) {
                            const name = loc.name;
                            const locationKey = JSON.stringify({ country, city, name });
                            const cb = document.querySelector("#loc-" + CSS.escape(String(loc.id != null ? loc.id : (country + "-" + city + "-" + name).replace(/\s/g, "-"))));
                            if (cb) {
                                cb.checked = isChecked;
                                if (isChecked) selectedLocations.add(locationKey); else selectedLocations.delete(locationKey);
                            }
                        });
                        const cityCheckboxEl = document.getElementById("city-checkbox-city-" + country.replace(/\s/g, "-") + "-" + (city || "default").replace(/\s/g, "-"));
                        if (cityCheckboxEl) cityCheckboxEl.checked = isChecked;
                    }
                    filterJobs();
                }
            }
        }

        window.filterJobs = function () {
            var departmentIdentifiers = getCheckedBoxes("departments");
            var jobTypeId = getCheckedBoxes("jobTypes");
            var locationName = getCheckedBoxes("locations");
            var searchText = document.getElementById("kh-hiro-searchText")?.value;

            if (locationName || departmentIdentifiers || searchText || jobTypeId) {
                groupJobs(departmentIdentifiers, locationName, searchText, jobTypeId);
            } else {
                bindJobs(jobList);
            }
        };

        function getCheckedBoxes(chkboxName) {
            var checkboxes = document.getElementsByName(chkboxName);
            var checkboxesChecked = [];
            if (chkboxName === "locations" || chkboxName === "departments") {
                for (var i = 0; i < checkboxes.length; i++) {
                    if (checkboxes[i].checked) {
                        checkboxesChecked.push(checkboxes[i].value);
                    }
                }
            } else {
                for (var i = 0; i < checkboxes.length; i++) {
                    if (checkboxes[i].checked) {
                        checkboxesChecked.push(parseInt(checkboxes[i].value));
                    }
                }
            }

            return checkboxesChecked;
        }

        window.clearAllFilters = function () {
            document.querySelectorAll('input[name="departments"]:checked').forEach(el => el.checked = false);
            document.querySelectorAll('input[name="locations"]:checked').forEach(el => el.checked = false);
            document.querySelectorAll('input[name="jobTypes"]:checked').forEach(el => el.checked = false);
            document.getElementById("kh-hiro-searchText").value = "";

            bindJobs(jobList);
        };

        function groupJobs(departmentIdentifiers, locationName, searchText, jobTypeId) {
            var jobs = jobList.filter(function (j) {
                var lNames = j.jobLocations.filter(lc => lc.name).map(l => l.name);
                var lCities = j.jobLocations.filter(lc => lc.city).map(l => l.city);
                var deptFilterValue = globalFilterGroupsData ? j.groupLinkIdentifier : j.departmentIdentifier;
                return (departmentIdentifiers.length === 0 || departmentIdentifiers.includes(deptFilterValue)) && (jobTypeId.length === 0 || jobTypeId.includes(j.jobType)) && (locationName.length === 0 || (lNames && lNames.length && locationName.some(ln => lNames.includes(ln))) || (lCities && lCities.length && locationName.some(lc => lCities.includes(lc))));
            });
            searchText === "" ? bindJobs(jobs) : bindJobs(jobs.filter(function (j) { return (j.title.toLowerCase().indexOf(searchText.toLowerCase()) !== -1 || j.departmentName.toLowerCase().indexOf(searchText.toLowerCase()) !== -1); }));

        }

        JobWidget();
        var date = new Date().getFullYear();
        if (document.getElementById("year")) {
            document.getElementById("year").innerText = date;
        }

        function accordion() {
            const accordionTitles = document.querySelectorAll(".kh-accordion-title");

            accordionTitles.forEach((accordionTitle) => {
                accordionTitle.addEventListener("click", () => {
                    if (accordionTitle.classList.contains("kh-is-open")) {
                        accordionTitle.classList.remove("kh-is-open");
                    } else {
                        accordionTitle.classList.add("kh-is-open");
                    }
                });
            });
        }
    }
})();

